	public int babbleSort(){
		boolean flag = true;
		int nullBox, cnt = 0;
		while (flag){
			flag = false;
			for(int i = this.sorted.length -1; i >= 1; i--){
				if(this.sorted[i] < this.sorted[i - 1]){
					nullBox = this.sorted[i];
					this.sorted[i] = this.sorted[i - 1];
					this.sorted[i - 1] = nullBox;
					flag = true;
					cnt++;
				}
			}
		}
		return cnt;
	}

	public int selectionSort(){
		int minj, cnt = 0, nullBox;
		for(int i = 0; i < this.sorted.length; i++){
			minj = i;
			for(int j = i; j < this.sorted.length; j++){
				if(this.sorted[j] < this.sorted[minj]){
					minj = j;
				}
			}
			if(i != minj){
				cnt++;
			}
			nullBox = this.sorted[i];
			this.sorted[i] = this.sorted[minj];
			this.sorted[minj] = nullBox;
		}
		return cnt;
	}

	public void insertionSort(){
		int v, j;
		for(int i = 1; i < this.sorted.length; i++){
			v = this.sorted[i];
			j = i - 1;
			while(j >= 0 && this.sorted[j] > v){
				this.sorted[j + 1] = this.sorted[j];
				j--;
			}
			this.sorted[j + 1] = v;
