class SolK {
    int n,k;
    int[] arr, stones;

    SolK(int n, int k){
        this.n = n;
        this.k = k;
        arr = new int[n];
        stones = new int[k+1];
    }

    void sol(){
        for(int i = 1; i <= k; ++i){
            int t = 1;
            int j = 0;
            for(; j < n && arr[j] <= i; ++j){
                t &= stones[i-(arr[j])];
            }
            stones[i]= j > 0 ? t^1 : j;
        }
        if(stones[k] == 1)
            System.out.println("First");
        else
            System.out.println("Second");
    }


